macro_rules! deps {
    () => {
        Service!();
        Protocol!();
    };
}

macro_rules! message {
    () => {
        deps!();
        mod message { use bstr :: { BString , ByteVec } ; use crate :: { Protocol , Service } ; pub fn connect (service : Service , desired_version : Protocol , path : & [u8] , virtual_host : Option < & (String , Option < u16 >) > , extra_parameters : & [(& str , Option < & str >)] ,) -> BString { let mut out = bstr :: BString :: from (service . as_str ()) ; out . push (b' ') ; let path = gix_url :: expand_path :: for_shell (path . into ()) ; out . extend_from_slice (& path) ; out . push (0) ; if let Some ((host , port)) = virtual_host { out . push_str ("host=") ; out . extend_from_slice (host . as_bytes ()) ; if let Some (port) = port { out . push_byte (b':') ; out . push_str (format ! ("{port}")) ; } out . push (0) ; } let extra_params_need_null_prefix = if desired_version != Protocol :: V1 { out . push (0) ; out . push_str (format ! ("version={}" , desired_version as usize)) ; out . push (0) ; false } else { true } ; if ! extra_parameters . is_empty () { if extra_params_need_null_prefix { out . push (0) ; } for (key , value) in extra_parameters { match value { Some (value) => out . push_str (format ! ("{key}={value}")) , None => out . push_str (key) , } out . push (0) ; } } out } # [cfg (test)] mod tests { use crate :: { client :: git , Protocol , Service } ; # [test] fn version_1_without_host_and_version () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V1 , b"hello/world" , None , & []) , "git-upload-pack hello/world\0") ; } # [test] fn version_2_without_host_and_version () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V2 , br"hello\world" , None , & []) , "git-upload-pack hello\\world\0\0version=2\0") ; } # [test] fn version_2_without_host_and_version_and_extra_parameters () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V2 , b"/path/project.git" , None , & [("key" , Some ("value")) , ("value-only" , None)]) , "git-upload-pack /path/project.git\0\0version=2\0key=value\0value-only\0") ; } # [test] fn with_host_without_port () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V1 , br"hello\world" , Some (& ("host" . into () , None)) , & []) , "git-upload-pack hello\\world\0host=host\0") ; } # [test] fn with_host_without_port_and_extra_parameters () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V1 , br"hello\world" , Some (& ("host" . into () , None)) , & [("key" , Some ("value")) , ("value-only" , None)]) , "git-upload-pack hello\\world\0host=host\0\0key=value\0value-only\0") ; } # [test] fn with_host_with_port () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V1 , br"hello\world" , Some (& ("host" . into () , Some (404))) , & []) , "git-upload-pack hello\\world\0host=host:404\0") ; } # [test] fn with_strange_host_and_port () { assert_eq ! (git :: message :: connect (Service :: UploadPack , Protocol :: V1 , b"--upload-pack=attack" , Some (& ("--proxy=other-attack" . into () , Some (404))) , & []) , "git-upload-pack --upload-pack=attack\0host=--proxy=other-attack:404\0" , "we explicitly allow possible `-arg` arguments to be passed to the git daemon - the remote must protect against exploitation, we don't want to prevent legitimate cases") ; } } }
    };
}

message!()